@title: '{i18n>Genres}'
entity Genres : cuid, sap.common.CodeList {
  parent   : Association to Genres @title: '{i18n>Genres.parent}';
  children : Composition of many Genres on children.parent = $self @title: '{i18n>Genres.children}'

@title: '{i18n>Authors}'
entity Authors : managed {
  key ID       : Integer @title: '{i18n>Authors.ID}';
  name         : String @mandatory @title: '{i18n>Authors.name}';
  dateOfBirth  : Date @title: '{i18n>Authors.dateOfBirth}';
  dateOfDeath  : Date @title: '{i18n>Authors.dateOfDeath}';
  placeOfBirth : String @title: '{i18n>Authors.placeOfBirth}';
  placeOfDeath : String @title: '{i18n>Authors.placeOfDeath}';
  books        : Association to many Books on books.author = $self @title: '{i18n>Authors.books}'

@title: '{i18n>Books}'
entity Books : managed {
  key ID   : Integer @title: '{i18n>Books.ID}';
  author   : Association to Authors @mandatory @title: '{i18n>Books.author}';
  title    : localized String @mandatory @title: '{i18n>Books.title}';
  descr    : localized String(2000) @title: '{i18n>Books.descr}';
  genre    : Association to Genres @title: '{i18n>Books.genre}';
  stock    : Integer @title: '{i18n>Books.stock}';
  price    : Price @title: '{i18n>Books.price}';
  currency : Currency @title: '{i18n>Books.currency}'

@title: '{i18n>CatalogService}'
service CatalogService @(odata:'/browse') {

  /** For displaying lists of Books */
  @title: '{i18n>ListOfBooks}'
  @readonly entity ListOfBooks as projection on Books {
    *, currency.symbol as currency,
  }
  excluding { descr };

  /** For display in details pages */
  @readonly entity Books as projection on my.Books { 
    *, // all fields with the following denormalizations:
    author.name as author, 
    genre.name as genre,
  } excluding { createdBy, modifiedBy };

  @title: '{i18n>submitOrder}'
  @requires: 'authenticated-user'
  action submitOrder ( book: Books:ID @title: '{i18n>submitOrder.book}', quantity: Integer @title: '{i18n>submitOrder.quantity}'

